function Logo({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className="flex items-center gap-2.5 focus-ring" data-testid="link-logo">
    <span className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Hammer size={18} strokeWidth={2.5} /></span>
    {!compact && <span className="font-display text-[19px] font-bold tracking-[-.04em]">work<span className="text-secondary">forge</span></span>}
  </Link>;
}

function Avatar({ person, size = 'md' }: { person: Pick<Freelancer, 'initials' | 'accent'> | { initials: string; accent?: string }; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'size-8 text-[11px]', md: 'size-11 text-sm', lg: 'size-20 text-xl' };
  return <span className={`${sizes[size]} ${person.accent ?? 'bg-[#d7e4ed]'} grid shrink-0 place-items-center rounded-2xl font-display font-bold text-foreground`} data-testid="img-avatar">{person.initials}</span>;
}

function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'outline' | 'quiet' | 'coral'; className?: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  const styles = {
    primary: 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-md',
    outline: 'border border-border bg-card text-foreground hover:border-primary hover:text-primary',
    quiet: 'text-muted-foreground hover:bg-muted hover:text-foreground',
    coral: 'bg-accent text-accent-foreground hover:-translate-y-0.5 hover:shadow-md',
  };
  return <button type={type} onClick={onClick} disabled={disabled} className={`focus-ring inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 text-sm font-semibold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} data-testid={`button-${variant}`}>{children}</button>;
}

function Badge({ children, tone = 'muted' }: { children: ReactNode; tone?: 'muted' | 'teal' | 'gold' | 'coral' }) {
  const tones = { muted: 'bg-muted text-muted-foreground', teal: 'bg-[#d8eee6] text-[#176354]', gold: 'bg-[#f5e6bf] text-[#765a19]', coral: 'bg-[#f3d9d3] text-[#99463c]' };
  return <span className={`inline-flex items-center rounded-md px-2.5 py-1 font-mono text-[10px] font-medium uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function Stars({ rating }: { rating: string }) {
  return <span className="inline-flex items-center gap-1 text-sm font-semibold"><Star size={14} className="fill-secondary text-secondary" /> {rating}</span>;
}

