        <Link href="/dashboard/freelancer" className="flex items-center gap-2 rounded-xl p-1.5 pr-2 transition-colors hover:bg-muted" data-testid="link-profile"><Avatar person={{ initials: 'AM', accent: 'bg-[#d7efe7]' }} size="sm" /><span className="hidden text-sm font-semibold lg:inline">Alex Morgan</span><ChevronDown size={14} className="text-muted-foreground" /></Link>
